# views.py
class PostViewSet(viewsets.ModelViewSet):
    serializer_class = PostSerializer
    permission_classes = [IsAuthenticatedOrReadOnly]  # protect method-level permissions too

    def get_queryset(self):
        return Post.objects.all()

    def perform_create(self, serializer):
        serializer.save(author=self.request.user)
```

That's the minimal boilerplate. You'll want `is_owner` or `is_author` permission checks too for full CRUD safety.
